package com.zjnu.lab.controller;
import com.zjnu.lab.common.*; import com.zjnu.lab.mapper.*; import com.zjnu.lab.model.RepairOrder; import com.zjnu.lab.util.SecurityUtil; import com.zjnu.lab.service.LabScopeService; import lombok.RequiredArgsConstructor; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController @RequiredArgsConstructor public class RepairController {private final RepairMapper mapper;private final DeviceMapper devices;private final LabScopeService scope;
 @GetMapping("/repairs/my") public ApiResponse<?> mine(@RequestParam(required=false)String status){return ApiResponse.ok(mapper.list(SecurityUtil.userId(),status,null));}
 @GetMapping("/manage/repairs") public ApiResponse<?> all(@RequestParam(required=false)String status){return ApiResponse.ok(mapper.list(null,status,scope.scope()));}
 @PostMapping("/repairs") @Transactional public ApiResponse<?> add(@Valid @RequestBody RepairOrder r){var device=devices.get(r.getDeviceId());if(device==null)throw new BusinessException("设备不存在");scope.requireAccess(device.getLabId());if(mapper.activeByReporter(r.getDeviceId(),SecurityUtil.userId())>0)throw new BusinessException("你已提交该设备的待处理工单");if(mapper.active(r.getDeviceId())>0)throw new BusinessException("该设备已有待处理工单");r.setReporterId(SecurityUtil.userId());mapper.insert(r);devices.updateStatus(r.getDeviceId(),"FAULT");return ApiResponse.ok(r);}
 public record Handle(String status,String result){}
 @PutMapping("/manage/repairs/{id}/handle") @Transactional public ApiResponse<?> handle(@PathVariable Long id,@RequestBody Handle h){Long labId=mapper.labId(id);if(labId==null)throw new BusinessException("工单不存在");scope.requireAccess(labId);RepairOrder current=mapper.list(null,null,scope.scope()).stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->new BusinessException("工单不存在"));String from=current.getStatus();boolean allowed=("PENDING".equals(from)&&"PROCESSING".equals(h.status()))||("PROCESSING".equals(from)&&"COMPLETED".equals(h.status()))||(("PENDING".equals(from)||"PROCESSING".equals(from))&&"CLOSED".equals(h.status()));if(!allowed)throw new BusinessException("工单状态流转不允许");if("COMPLETED".equals(h.status())&&(h.result()==null||h.result().isBlank()))throw new BusinessException("完成维修必须填写处理结果");if(mapper.handle(id,SecurityUtil.userId(),h.status(),from,h.result())!=1)throw new BusinessException("工单状态已变化");Long did=mapper.deviceId(id);String deviceStatus=switch(h.status()){case "PROCESSING"->"MAINTENANCE";case "COMPLETED"->"NORMAL";case "CLOSED"->"FAULT";default->throw new BusinessException("维修状态无效");};devices.updateStatus(did,deviceStatus);return ApiResponse.ok();}
}
